/// Runs the on_event hook for all plugins in the store.
pub(crate) fn on_event(&mut self, app: &AppHandle<R>, event: &RunEvent) {
  self
    .store
    .iter_mut()
    .for_each(|plugin| plugin.on_event(app, event))
}

macro_rules! getter {
  ($self: ident, $rx: expr, $message: expr) => {{
    $self.context.send_user_message($message)?;
    $rx
      .recv()
      .map_err(|_| $crate::Error::FailedToReceiveMessage)
  }};
}

macro_rules! window_getter {
  ($self: ident, $message: expr) => {{
    let (tx, rx) = channel();
    getter!($self, rx, Message::Window($self.window_id, $message(tx)))
  }};
}

fn send_user_message(&self, message: Message<T>) -> Result<()> {
  if current_thread().id() == self.main_thread_id {
    handle_user_message(
      &self.main_thread.window_target,
      message,
      UserMessageContext {
        window_id_map: &self.window_id_map,
        windows: &self.main_thread.windows,
      },
    );
    Ok(())
  } else {
    self
      .proxy
      .send_event(message)
      .map_err(|_| Error::FailedToSendMessage)
  }
}

